package org.jsoup.nodes;

import org.jsoup.helper.Validate;
import org.jsoup.helper.Regex;
import org.jsoup.nodes.Document;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Nodes;
import org.jsoup.select.Selector;
import org.jsoup.parser.Parser;
import org.jspecify.annotations.Nullable;

import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import java.util.stream.Stream;

/**
 * Helper class to centralize selection/query/collection responsibilities extracted from Element.
 * All methods are static and take an Element (and params) and perform the original logic.
 */
public final class ElementSelector {
    private ElementSelector() {
    }

    public static Elements select(Element el, String cssQuery) {
        return Selector.select(cssQuery, el);
    }

    public static Elements select(Element el, Evaluator evaluator) {
        return Selector.select(evaluator, el);
    }

    public static Stream<Element> selectStream(Element el, String cssQuery) {
        return Selector.selectStream(cssQuery, el);
    }

    public static Stream<Element> selectStream(Element el, Evaluator evaluator) {
        return Selector.selectStream(evaluator, el);
    }

    @Nullable
    public static Element selectFirst(Element el, String cssQuery) {
        return Selector.selectFirst(cssQuery, el);
    }

    @Nullable
    public static Element selectFirst(Element el, Evaluator evaluator) {
        return Collector.findFirst(evaluator, el);
    }

    public static Element expectFirst(Element el, String cssQuery) {
        return Validate.expectNotNull(
            Selector.selectFirst(cssQuery, el),
            el.parent() != null ?
                "No elements matched the query '%s' on element '%s'." :
                "No elements matched the query '%s' in the document."
        , cssQuery, el.tagName());
    }

    // Nodes selection
    public static Nodes<Node> selectNodes(Element el, Evaluator evaluator) {
        return Collector.collectNodes(evaluator, el, Node.class);
    }

    public static Nodes<Node> selectNodes(Element el, String cssQuery) {
        return selectNodes(el, Selector.evaluatorOf(cssQuery));
    }

    public static <T extends Node> Nodes<T> selectNodes(Element el, Evaluator evaluator, Class<T> type) {
        Validate.notNull(evaluator);
        return Collector.collectNodes(evaluator, el, type);
    }

    public static <T extends Node> Nodes<T> selectNodes(Element el, String cssQuery, Class<T> type) {
        Validate.notEmpty(cssQuery);
        return selectNodes(el, Selector.evaluatorOf(cssQuery), type);
    }

    @Nullable
    public static <T extends Node> T selectFirstNode(Element el, String cssQuery, Class<T> type) {
        return selectFirstNode(el, Selector.evaluatorOf(cssQuery), type);
    }

    @Nullable
    public static <T extends Node> T selectFirstNode(Element el, Evaluator evaluator, Class<T> type) {
        return Collector.findFirstNode(evaluator, el, type);
    }

    public static <T extends Node> T expectFirstNode(Element el, String cssQuery, Class<T> type) {
        return Validate.expectNotNull(
            selectFirstNode(el, cssQuery, type),
            el.parent() != null ?
                "No nodes matched the query '%s' on element '%s'.":
                "No nodes matched the query '%s' in the document."
            , cssQuery, el.tagName()
        );
    }

    public static boolean is(Element el, String cssQuery) {
        return is(el, Selector.evaluatorOf(cssQuery));
    }

    public static boolean is(Element el, Evaluator evaluator) {
        return evaluator.matches(el.root(), el);
    }

    @Nullable
    public static Element closest(Element el, String cssQuery) {
        return closest(el, Selector.evaluatorOf(cssQuery));
    }

    @Nullable
    public static Element closest(Element el, Evaluator evaluator) {
        Validate.notNull(evaluator);
        Element cur = el;
        final Element root = el.root();
        do {
            if (evaluator.matches(root, cur))
                return cur;
            cur = cur.parent();
        } while (cur != null);
        return null;
    }

    // xpath selection - delegates to NodeUtils
    public static Elements selectXpath(Element el, String xpath) {
        return new Elements(NodeUtils.selectXpath(xpath, el, Element.class));
    }

    public static <T extends Node> List<T> selectXpath(Element el, String xpath, Class<T> nodeType) {
        return NodeUtils.selectXpath(xpath, el, nodeType);
    }

    // DOM-type helpers
    public static Elements getElementsByTag(Element el, String tagName) {
        Validate.notEmpty(tagName);
        tagName = tagName; // normalize if required by caller
        return Collector.collect(new Evaluator.Tag(tagName), el);
    }

    @Nullable
    public static Element getElementById(Element el, String id) {
        Validate.notEmpty(id);
        return Collector.findFirst(new Evaluator.Id(id), el);
    }

    public static Elements getElementsByClass(Element el, String className) {
        Validate.notEmpty(className);
        return Collector.collect(new Evaluator.Class(className), el);
    }

    public static Elements getElementsByAttribute(Element el, String key) {
        Validate.notEmpty(key);
        key = key.trim();
        return Collector.collect(new Evaluator.Attribute(key), el);
    }

    public static Elements getElementsByAttributeStarting(Element el, String keyPrefix) {
        Validate.notEmpty(keyPrefix);
        keyPrefix = keyPrefix.trim();
        return Collector.collect(new Evaluator.AttributeStarting(keyPrefix), el);
    }

    public static Elements getElementsByAttributeValue(Element el, String key, String value) {
        return Collector.collect(new Evaluator.AttributeWithValue(key, value), el);
    }

    public static Elements getElementsByAttributeValueNot(Element el, String key, String value) {
        return Collector.collect(new Evaluator.AttributeWithValueNot(key, value), el);
    }

    public static Elements getElementsByAttributeValueStarting(Element el, String key, String valuePrefix) {
        return Collector.collect(new Evaluator.AttributeWithValueStarting(key, valuePrefix), el);
    }

    public static Elements getElementsByAttributeValueEnding(Element el, String key, String valueSuffix) {
        return Collector.collect(new Evaluator.AttributeWithValueEnding(key, valueSuffix), el);
    }

    public static Elements getElementsByAttributeValueContaining(Element el, String key, String match) {
        return Collector.collect(new Evaluator.AttributeWithValueContaining(key, match), el);
    }

    public static Elements getElementsByAttributeValueMatching(Element el, String key, Pattern pattern) {
        return Collector.collect(new Evaluator.AttributeWithValueMatching(key, pattern), el);
    }

    public static Elements getElementsByAttributeValueMatching(Element el, String key, String regex) {
        Pattern pattern;
        try {
            pattern = Pattern.compile(regex);
        } catch (PatternSyntaxException e) {
            throw new IllegalArgumentException("Pattern syntax error: " + regex, e);
        }
        return Collector.collect(new Evaluator.AttributeWithValueMatching(key, pattern), el);
    }

    public static Elements getElementsByIndexLessThan(Element el, int index) {
        return Collector.collect(new Evaluator.IndexLessThan(index), el);
    }

    public static Elements getElementsByIndexGreaterThan(Element el, int index) {
        return Collector.collect(new Evaluator.IndexGreaterThan(index), el);
    }

    public static Elements getElementsByIndexEquals(Element el, int index) {
        return Collector.collect(new Evaluator.IndexEquals(index), el);
    }

    public static Elements getElementsContainingText(Element el, String searchText) {
        return Collector.collect(new Evaluator.ContainsText(searchText), el);
    }

    public static Elements getElementsContainingOwnText(Element el, String searchText) {
        return Collector.collect(new Evaluator.ContainsOwnText(searchText), el);
    }

    public static Elements getElementsMatchingText(Element el, Pattern pattern) {
        return Collector.collect(new Evaluator.Matches(pattern), el);
    }

    public static Elements getElementsMatchingText(Element el, String regex) {
        Pattern pattern;
        try {
            pattern = Pattern.compile(regex);
        } catch (PatternSyntaxException e) {
            throw new IllegalArgumentException("Pattern syntax error: " + regex, e);
        }
        return Collector.collect(new Evaluator.Matches(pattern), el);
    }

    public static Elements getElementsMatchingOwnText(Element el, Pattern pattern) {
        return Collector.collect(new Evaluator.MatchesOwn(pattern), el);
    }

    public static Elements getElementsMatchingOwnText(Element el, String regex) {
        Pattern pattern;
        try {
            pattern = Pattern.compile(regex);
        } catch (PatternSyntaxException e) {
            throw new IllegalArgumentException("Pattern syntax error: " + regex, e);
        }
        return Collector.collect(new Evaluator.MatchesOwn(pattern), el);
    }

    public static Elements getAllElements(Element el) {
        return Collector.collect(new Evaluator.AllElements(), el);
    }

    public static Evaluator evaluatorOf(String cssQuery) {
        return Selector.evaluatorOf(cssQuery);
    }
}
